/* wiki-formeln.js - Tonfunk Wiki, Kategorien Formeln und Normwerte (Schulwissen aus den Berufsschul-Aufzeichnungen, eigene Formulierungen).
 * Erzeugt mit quelle/gen/mk_schulwissen.js aus quelle/schule/out/*.json - nicht von Hand aendern. Alle Eintraege starten mit status 'entwurf' (Fachpruefung durch die Ausbilder). */
(function (arr) { if (typeof module !== 'undefined' && module.exports) module.exports = arr; else window.Wiki.add('formeln', arr); })([
  {"id":"fo-arbeitsgerade","kat":"formel","titel":"Arbeitspunkt grafisch bestimmen","kurz":"Bei zwei Bauteilen in Reihe zeichnest du die Kennlinie des einen und die an der Spannungsachse gespiegelte, um die Gesamtspannung verschobene Kennlinie des anderen. Der Schnittpunkt ist der Arbeitspunkt.","lang":"**Vorgehen** (Reihenschaltung aus Bauteil 1 und Widerstand 2 an U_B):\n\n1. Kennlinie von Bauteil 1 einzeichnen (I über U₁). Beim Widerstand genügt der Nullpunkt und ein weiterer Punkt.\n2. Arbeitsgerade von Widerstand 2: Punkt (U = 0 | I = U_B / R₂) und Punkt (U = U_B | I = 0) verbinden.\n3. Im Schnittpunkt Strom und Spannung ablesen: U₁ auf der Spannungsachse, U₂ = U_B − U₁.\n\nÜbungswert: R₁ = 200 Ω, R₂ = 300 Ω, U_B = 30 V. Arbeitsgerade von R₂ durch (0 V | 100 mA) und (30 V | 0). Kennlinie von R₁ durch (0 | 0) und (30 V | 150 mA). Schnittpunkt bei I = 60 mA, U₁ = 12 V, U₂ = 18 V. Rechnerisch: I = 30 V / 500 Ω = 60 mA.\n\nÄnderst du U_B, verschiebt sich die Arbeitsgerade parallel; änderst du R₂, ändert sich ihre Steigung. Belastest du R₁ mit mehr als seiner zulässigen Verlustleistung, hilft ein größerer R₂.\n\nSiehe [[bg-arbeitspunkt|Arbeitspunkt]] und [[fo-reihe-parallel|Reihenschaltung]]. Kennlinien messbar mit dem [[ger-kennlinie|Kennlinienschreiber]].","verweise":["bg-arbeitspunkt","fo-reihe-parallel","ger-kennlinie"],"labs":["ana","sim","mess"],"stich":["Arbeitspunkt","Arbeitsgerade","Kennlinie","Schnittpunkt","grafische Lösung"],"pruef":3,"status":"entwurf","formeln":[{"text":"I_AP = U_B / (R₁ + R₂)"},{"text":"Achsenpunkt: I_max = U_B / R₂"}]},
  {"id":"fo-laengsregler","kat":"formel","titel":"Ausgangsspannung der Längsregelung mit Z-Diode","kurz":"Bei einem Emitterfolger mit Z-Diode ist die Ausgangsspannung etwa U_a = U_Z − U_BE. Der Transistor liefert den Laststrom, die Z-Diode nur den kleinen Basisstrom.","lang":"Der Längstransistor verstärkt den Strom: Der Laststrom ist etwa B-mal so groß wie der Basisstrom. Die Z-Diode wird daher nur gering belastet und stabilisiert besser als bei direkter Last.\n\nBeispiel (Übungswert): U_Z = 9,1 V, U_BE = 0,7 V: U_a ≈ 8,4 V. Bei Stromverstärkung B = 100 und Laststrom 500 mA beträgt der Basisstrom 5 mA. Die Verlustleistung des Transistors ist P = (U_e − U_a) · I_L, bei U_e = 12 V also 3,6 V · 0,5 A = 1,8 W. Sie muss über einen Kühlkörper abgeführt werden können.\n\nBauteile: [[bt-npn|Transistor]], [[bt-d|Z-Diode]]; Einordnung: [[bg-spannungsstabilisierung|Spannungsstabilisierung]].","verweise":["bt-npn","bt-d","bg-spannungsstabilisierung"],"labs":["nts","sim"],"stich":["Längsregler","Emitterfolger","Ausgangsspannung"],"pruef":2,"formeln":[{"text":"U_a = U_Z − U_BE"},{"text":"P_V = (U_e − U_a) · I_L"},{"text":"I_B = I_L / B"}],"status":"entwurf"},
  {"id":"fo-ausschussquote","kat":"formel","titel":"Ausschussquote und Ausbeute","kurz":"Die Ausschussquote gibt den Anteil fehlerhafter Teile an der Gesamtmenge in Prozent an. Die Ausbeute (Gutquote) ist der Anteil der brauchbaren Teile. Beide ergänzen sich zu 100 Prozent.","lang":"**Rechnung**\n\nAusschussquote = Anzahl Ausschussteile durch Gesamtzahl der gefertigten Teile, mal 100 Prozent. Die Ausbeute ist der Rest.\n\n**Beispiel**\n\nVon 400 gefertigten Baugruppen sind 12 nicht zu gebrauchen. Die Ausschussquote ist 12 : 400 mal 100 Prozent = 3 Prozent. Die Ausbeute beträgt 97 Prozent.\n\n**Bedeutung**\n\nDer Ausschuss gehört zu den internen Fehlerkosten ([[bg-qualitaetskosten|Qualitätskosten]]). Wer wissen will, welche Fehlerarten ihn verursachen, ordnet sie im [[bg-pareto|Pareto-Diagramm]]. Prozentrechnung allgemein: [[fo-prozentrechnung|Prozentrechnung]].","formeln":[{"text":"Ausschussquote = Ausschuss / Gesamtmenge · 100 %"},{"text":"Ausbeute = Gutteile / Gesamtmenge · 100 % = 100 % − Ausschussquote"}],"verweise":["bg-qualitaetskosten","bg-pareto","fo-prozentrechnung"],"labs":["pr","mess"],"stich":["Ausschuss","Ausschussquote","Ausbeute","Yield","Gutquote","Fehlerquote"],"pruef":3,"status":"entwurf"},
  {"id":"fo-basisvorwiderstand","kat":"formel","titel":"Basisvorwiderstand und Stromverstärkung","kurz":"Der Basisvorwiderstand ergibt sich aus der Spannung, die an ihm abfallen muss, geteilt durch den Basisstrom: R_B = (U_B − U_BE) / I_B. Der Basisstrom folgt aus I_B = I_C / B.","lang":"**Stromverstärkung**: B = I_C / I_B.\n\n**Verstärkerbetrieb**: Aus dem gewünschten Kollektorstrom und B bestimmst du I_B. Übungswert: U_B = 12 V, U_BE = 0,7 V, I_B = 0,2 mA ergibt R_B = 11,3 V / 0,2 mA ≈ 56,5 kΩ.\n\n**Schalterbetrieb**: Der Basisstrom wird um den Übersteuerungsfaktor ü größer gewählt: I_B = ü · I_C / B. Übungswert: I_C = 20 mA, B = 100, ü = 3 ergibt I_B = 0,6 mA, R_B = 11,3 V / 0,6 mA ≈ 18,8 kΩ. Aus der E12-Reihe passt 18 kΩ (I_B ≈ 0,63 mA).\n\n**Verlustleistung** des Transistors: P_V = U_CE · I_C. Beispiel Längstransistor: U_CE = 6 V, I_C = 0,8 A ergibt 4,8 W, das macht eine Kühlung nötig ([[bg-kuehlung-halbleiter|Kühlung]]).\n\nHintergrund: [[bg-transistor-kennlinien|Kennlinien]], [[bg-arbeitspunkteinstellung|Arbeitspunkteinstellung]], Schaltbetrieb in [[bg-transistor-betriebszustaende|Betriebszuständen]]. Bauteil: [[bt-npn|Transistor]].","verweise":["bg-kuehlung-halbleiter","bg-transistor-kennlinien","bg-arbeitspunkteinstellung","bg-transistor-betriebszustaende","bt-npn"],"labs":["ana","sim","digi"],"stich":["R_B","Basiswiderstand","Gleichstromverstärkung","Übersteuerungsfaktor","I_B"],"pruef":3,"status":"entwurf","formeln":[{"text":"R_B = (U_B − U_BE) / I_B"},{"text":"I_B = ü · I_C / B"},{"text":"P_V = U_CE · I_C"}]},
  {"id":"nw-8085-befehle","kat":"norm","titel":"Befehlsübersicht eines klassischen 8-Bit-Prozessors","kurz":"Auswahl häufiger Befehle eines 8-Bit-Prozessors vom Typ 8085 mit Mnemonik, Maschinencode in hexadezimaler Schreibweise und Wirkung. Zur Orientierung beim Programmieren in Assembler.","lang":"Auswahl (Maschinencode hexadezimal, Übungswert zur Orientierung):\n- IN p / OUT p: Port lesen in den Akku / Akku an Port ausgeben (Code DB / D3, zweites Byte Portadresse)\n- MVI A, n: Akku mit Zahl laden (3E n); MVI B, n (06 n); MVI C, n (0E n)\n- MOV A, B (78); MOV B, A (47); MOV A, C (79)\n- LDA adr / STA adr: Akku aus Speicher laden / in Speicher schreiben (3A / 32, danach Adresse niederwertig, höherwertig)\n- LXI H, nn: Registerpaar H/L laden (21)\n- ADD B (80); ADI n (C6 n); SUB B (90); SUI n (D6 n)\n- ANI n (E6 n); ORA B (B0); CMA: Akku invertieren (2F)\n- INR A (3C); INR C (0C); DCR A (3D); DCR B (05)\n- RAL: Akku links durch Carry schieben (17)\n- JMP adr: unbedingter Sprung (C3); JZ adr: Sprung wenn Zero = 1 (CA); JNZ adr: Sprung wenn Zero = 0 (C2); JC adr: Sprung wenn Carry = 1 (DA)\n- PUSH B (C5); POP B (C1)\n- EI (FB); DI (F3); NOP (00); HLT (76)","verweise":["bg-assembler","bg-adressierung","bg-flags"],"labs":["code","digi"],"stich":["Befehl","Mnemonik","Maschinencode","Opcode","8085"],"pruef":2,"status":"entwurf"},
  {"id":"fo-blindwiderstand","kat":"formel","titel":"Blindwiderstände und Blindleistung","kurz":"Der induktive Blindwiderstand ist X_L = 2π · f · L, der kapazitive X_C = 1 / (2π · f · C). Aus Spannung und Blindwiderstand folgen der Strom I = U / X und die Blindleistung Q = U · I.","lang":"**Induktiv**: X_L = ω · L = 2π · f · L, Einheit Ω. Der Strom eilt der Spannung um 90° nach.\n**Kapazitiv**: X_C = 1 / (ω · C) = 1 / (2π · f · C). Der Strom eilt der Spannung um 90° voraus.\n\nStrom und Blindleistung: I = U / X, Q = U · I = I² · X (Einheit var).\n\nÜbungswert Spule: L = 2 H, f = 50 Hz, U = 230 V. X_L = 2π · 50 · 2 ≈ 628 Ω, I ≈ 0,37 A, Q ≈ 84 var.\n\nÜbungswert Kondensator: C = 16 µF, f = 50 Hz, U = 230 V. X_C ≈ 199 Ω, I ≈ 1,16 A, Q ≈ 266 var.\n\nLiegen Wirk- und Blindwiderstand in Reihe, addierst du sie geometrisch: Z = √(R² + X²), nicht einfach als Summe. Wichtig ist die Frequenzabhängigkeit: X_L steigt, X_C sinkt mit der Frequenz. Daraus folgt das Verhalten von RC-Hoch- und Tiefpässen.\n\nGrundlagen: [[bg-blindwiderstand|Wirk- und Blindwiderstand]], [[bg-wechselspannung|Wechselspannung]]. Bauteile: [[bt-l|Spule]], [[bt-c|Kondensator]].","verweise":["bg-blindwiderstand","bg-wechselspannung","bt-l","bt-c"],"labs":["wsl","sim","mess"],"stich":["X_L","X_C","Blindwiderstand","Impedanz","Blindleistung","var","Kreisfrequenz"],"pruef":3,"status":"entwurf","formeln":[{"text":"X_L = 2π · f · L"},{"text":"X_C = 1 / (2π · f · C)"},{"text":"Z = √(R² + X²)"}]},
  {"id":"fo-boole-gesetze","kat":"formel","titel":"Boolesche Gesetze","kurz":"Die Schaltalgebra kennt feste Rechenregeln wie Kommutativ-, Assoziativ-, Distributiv-, Absorptionsgesetz und die Regeln von De Morgan. Mit ihnen lassen sich Logikgleichungen vereinfachen.","lang":"Wichtige Regeln (UND als Punkt, ODER als Plus, Negation durch Überstrich beziehungsweise NICHT):\n\n- Kommutativ: A + B = B + A, A · B = B · A.\n- Distributiv: A · (B + C) = A · B + A · C.\n- Absorption: A + A · B = A; A · (A + B) = A.\n- Komplement: A + NICHT A = 1; A · NICHT A = 0.\n- De Morgan: NICHT (A · B) = NICHT A + NICHT B; NICHT (A + B) = NICHT A · NICHT B.\n- Nützlich: A + NICHT A · B = A + B.\n\nBeispiel (Übungswert): Z = A · B + A · NICHT B = A · (B + NICHT B) = A · 1 = A.\n\nDe Morgan erlaubt, ein UND mit Negationen als NOR aufzubauen oder ein ODER als NAND. Das ist wichtig, wenn nur ein Gattertyp vorhanden ist. Anwendung: [[bg-logiksynthese|Logiksynthese]] und [[bg-normalform|Normalform]]; grafisch geht es mit dem [[bg-kv-diagramm|KV-Diagramm]].","verweise":["bg-logiksynthese","bg-normalform","bg-kv-diagramm"],"labs":["digi"],"stich":["De Morgan","Boole","Schaltalgebra","Absorption","Distributiv"],"pruef":3,"formeln":[{"text":"NICHT (A · B) = NICHT A + NICHT B"},{"text":"NICHT (A + B) = NICHT A · NICHT B"},{"text":"A + A · B = A"},{"text":"A + NICHT A · B = A + B"}],"status":"entwurf"},
  {"id":"fo-schlupf-drehzahl","kat":"formel","titel":"Drehfelddrehzahl und Schlupf","kurz":"Die Drehfelddrehzahl ist n₀ = f / p, der Schlupf s = (n₀ − n) / n₀ gibt an, wie weit die Läuferdrehzahl n unter dem Drehfeld liegt.","lang":"**Synchrone Drehzahl**: n₀ = f / p mit Netzfrequenz f und Polpaarzahl p. Bei 50 Hz: p = 1 ergibt 3000 min⁻¹, p = 2 ergibt 1500 min⁻¹, p = 3 ergibt 1000 min⁻¹, p = 4 ergibt 750 min⁻¹. Die Polzahl ist 2p.\n\n**Schlupf**: s = (n₀ − n) / n₀, oft in Prozent. Übungswert: n₀ = 1500 min⁻¹, n = 1440 min⁻¹ ergibt s = 60 / 1500 = 4 %. Die Läuferfrequenz ist f₂ = s · f₁ = 2 Hz.\n\nIm Leerlauf ist s sehr klein, im Stillstand ist s = 1, beim Generatorbetrieb (n > n₀) ist s negativ.\n\nSiehe [[bg-asynchronmotor|Asynchronmotor]] und [[bg-drehstrom|Drehstrom]].","verweise":["bg-asynchronmotor","bg-drehstrom"],"labs":["ant","enr"],"stich":["Drehzahl","Polpaarzahl","Synchrondrehzahl","Schlupf","Läuferfrequenz"],"pruef":2,"status":"entwurf","formeln":[{"text":"n₀ = f / p"},{"text":"s = (n₀ − n) / n₀"},{"text":"f₂ = s · f₁"}]},
  {"id":"fo-drehstrom-leistung","kat":"formel","titel":"Drehstromleistung und Verkettung","kurz":"Bei symmetrischer Last gilt P = √3 · U · I · cos φ mit der Außenleiterspannung U und dem Leiterstrom I. In Stern ist U = √3 · U_Str, in Dreieck ist I = √3 · I_Str.","lang":"**Verkettung**: Stern: U = √3 · U_Str, I = I_Str. Dreieck: U = U_Str, I = √3 · I_Str. Der Faktor √3 beträgt etwa 1,73.\n\n**Leistungen** (symmetrische Last): Wirkleistung P = √3 · U · I · cos φ in W, Scheinleistung S = √3 · U · I in VA, Blindleistung Q = √3 · U · I · sin φ in var.\n\nÜbungswert: U = 400 V, I = 10 A, cos φ = 0,8 ergibt S ≈ 6,93 kVA und P ≈ 5,54 kW.\n\nEinphasig mit 230 V und gleichem Strom wären es nur P = U · I · cos φ. Dieselbe Wicklung nimmt in Dreieck dreimal so viel Leistung auf wie in Stern.\n\nZu den Schaltungen siehe [[bg-sternschaltung|Stern]] und [[bg-dreieckschaltung|Dreieck]], zu den Netzen [[bg-drehstrom|Drehstrom]]. Verbraucher: [[bt-motor|Motor]]; Messen mit dem [[ger-leistung|Leistungsmesser]].","verweise":["bg-sternschaltung","bg-dreieckschaltung","bg-drehstrom","bt-motor","ger-leistung"],"labs":["enr","ant","haus"],"stich":["Wirkleistung","Scheinleistung","cos phi","Leistungsfaktor","Wurzel 3","Verkettungsfaktor"],"pruef":3,"status":"entwurf","formeln":[{"text":"P = √3 · U · I · cos φ"},{"text":"S = √3 · U · I"},{"text":"Stern: U = √3 · U_Str"},{"text":"Dreieck: I = √3 · I_Str"}]},
  {"id":"fo-dreisatz","kat":"formel","titel":"Dreisatz (proportional und antiproportional)","kurz":"Der Dreisatz rechnet von einer bekannten Größe auf eine gesuchte um. Bei proportionalen Größen wächst das Ergebnis mit, bei antiproportionalen Größen fällt es, wenn die andere Größe wächst.","lang":"**Proportional (je mehr, desto mehr)**\n\nVerhältnis gleich: gesuchter Wert = bekannter Wert mal neue Menge durch alte Menge. Beispiel: 5 Widerstände kosten 2 €. 12 Widerstände kosten 2 € · 12 / 5 = 4,80 €.\n\n**Antiproportional (je mehr, desto weniger)**\n\nDas Produkt bleibt gleich. Beispiel: 3 Personen brauchen für eine Arbeit 12 Tage. 4 Personen brauchen 3 · 12 / 4 = 9 Tage.\n\n**Schrittfolge**\n\n1. Bedingungssatz: Was ist bekannt?\n2. Rückschluss auf die Einheit (eine Person, ein Stück).\n3. Schluss auf die gesuchte Menge.\n\n**Anwendungen im Beruf**\n\nUmrechnen von Urlaubstagen ([[bg-urlaubsanspruch|Urlaubsanspruch]]: 24 Werktage bei sechs Wochentagen entsprechen 20 bei fünf), Materialmengen, Zeitplanung. Für Anteile in Prozent siehe [[fo-prozentrechnung|Prozentrechnung]].","formeln":[{"text":"proportional: y₂ = y₁ · x₂ / x₁"},{"text":"antiproportional: y₂ = y₁ · x₁ / x₂"}],"verweise":["bg-urlaubsanspruch","fo-prozentrechnung"],"labs":["pr","sch"],"stich":["Dreisatz","proportional","antiproportional","Verhältnisgleichung"],"pruef":2,"status":"entwurf"},
  {"id":"fo-dual-dezimal","kat":"formel","titel":"Dualzahl in Dezimalzahl umrechnen","kurz":"Jede Stelle einer Dualzahl hat den Wert einer Zweierpotenz. Die Summe der Stellen mit Ziffer 1 ergibt die Dezimalzahl. Umgekehrt zerlegt man eine Dezimalzahl in Zweierpotenzen.","lang":"Die Stellenwerte von rechts nach links sind 1, 2, 4, 8, 16, 32, 64, 128 und so weiter (2 hoch 0, 2 hoch 1, ...).\n\nBeispiel (Übungswert): 1011 0110 = 128 + 32 + 16 + 4 + 2 = 182.\n\nDezimal nach dual: Zerlege die Zahl in Zweierpotenzen oder teile fortlaufend durch 2 und notiere die Reste von unten nach oben. Beispiel: 45 = 32 + 8 + 4 + 1, also 10 1101. Probe: 32 + 8 + 4 + 1 = 45.\n\nZusammen mit [[fo-hex-dual|Hexadezimal]] sind Dualzahlen die Grundlage der Maschinenprogramme ([[bg-assembler|Assembler]]). Wie viele Werte n Bit darstellen, zeigt [[fo-wertebereich|Wertebereich]].","verweise":["fo-hex-dual","bg-assembler","fo-wertebereich"],"labs":["digi"],"stich":["Dual","Binär","Zahlensystem","Umrechnen"],"pruef":3,"formeln":[{"text":"Z = Σ aₙ · 2ⁿ (aₙ = 0 oder 1)"},{"text":"1011 0110₂ = 182₁₀"}],"status":"entwurf"},
  {"id":"fo-energiekosten","kat":"formel","titel":"Energie, Ladung und Kosten","kurz":"Elektrische Arbeit ist Leistung mal Zeit, E = P · t, die Kosten ergeben sich aus der Arbeit in kWh mal Strompreis. Die Ladung eines Akkus ist Strom mal Zeit, Q = I · t.","lang":"**Arbeit** E = P · t. In Wh oder kWh: Leistung in W oder kW mal Zeit in h. Kosten K = E · Preis (€/kWh).\n\nÜbungswert: Ein Motor mit 1,5 kW läuft 4 h am Tag, 5 Tage pro Woche, 46 Wochen im Jahr, also 920 h. E = 1,5 kW · 920 h = 1380 kWh. Bei 0,45 €/kWh (Übungswert) kostet das 621 € im Jahr.\n\nBei Dauerlast oder zyklischer Last bestimmst du erst die Betriebszeit: Ein Gerät, das 5 min pro Stunde läuft, kommt auf 2 h am Tag und 730 h im Jahr. Umrechnung: 1 kcal entspricht etwa 1,163 Wh.\n\n**Ladung und Strom**: Q = I · t (Einheit As oder Ah). Übungswert: Ein Akku mit 3200 mAh und einer Last von 250 mA reicht etwa 12,8 h. Die **Stromdichte** ist J = I / A in A/mm².\n\nDie Leistung selbst berechnest du aus [[fo-reihe-parallel|U und I]]; im Drehstromnetz gilt [[fo-drehstrom-leistung|P = √3 · U · I · cos φ]]. Messen kannst du die Energie mit dem [[ger-leistung|Leistungsmesser]].","verweise":["fo-reihe-parallel","fo-drehstrom-leistung","ger-leistung"],"labs":["enr","haus","sim"],"stich":["kWh","Leistung","Stromkosten","Betriebskosten","Ladung","Akkukapazität","Verbrauch"],"pruef":2,"status":"entwurf","formeln":[{"text":"E = P · t"},{"text":"K = E · Preis"},{"text":"Q = I · t"}]},
  {"id":"fo-fan-out","kat":"formel","titel":"Fan-out-Rechnung","kurz":"Der Fan-out eines Ausgangs ergibt sich aus dem höchsten Ausgangsstrom geteilt durch den Strom eines Normaleingangs. Die Summe der angeschlossenen Fan-in-Werte darf ihn nicht überschreiten.","lang":"Für Standard-TTL gilt im L-Zustand: I_OL(max) = 16 mA, I_IL = 1,6 mA je Eingang, also Fan-out = 16 mA / 1,6 mA = 10. Im H-Zustand: I_OH(max) = 0,4 mA, I_IH = 40 µA, ebenfalls 10.\n\nBeispiel (Übungswert): Ein Gatter treibt drei Gatter mit Fan-in 3, 2 und 1. Summe 6, zulässig 10, es bleiben 4 Normaleingänge frei. Der tatsächliche L-Strom ist dann 6 · 1,6 mA = 9,6 mA, der H-Strom 6 · 40 µA = 240 µA.\n\nHintergrund: [[bg-lastfaktoren|Lastfaktoren]] und [[bg-ttl|TTL]]. Werte in [[nw-ttl-pegel|TTL-Richtwerte]].","verweise":["bg-lastfaktoren","bg-ttl","nw-ttl-pegel"],"labs":["digi"],"stich":["Fan-out","Lastfaktor","Belastung"],"pruef":3,"formeln":[{"text":"FO = I_OL(max) / I_IL"},{"text":"I_Last = Summe(Fan-in) · I_IL"}],"status":"entwurf"},
  {"id":"fo-555-astabil","kat":"formel","titel":"Frequenz des 555 (astabil)","kurz":"Im astabilen Betrieb des 555 sind t_H = 0,693 · (R1 + R2) · C und t_L = 0,693 · R2 · C. Die Frequenz ist etwa 1,44 / ((R1 + 2 · R2) · C).","lang":"Der Kondensator pendelt zwischen einem Drittel und zwei Dritteln der Betriebsspannung. Er lädt über R1 und R2 (High-Zeit), entlädt über R2 (Low-Zeit). Daraus folgt: T = t_H + t_L = 0,693 · (R1 + 2 · R2) · C und f = 1 / T. Das Tastverhältnis ist stets größer als 50 %.\n\nBeispiel (Übungswert): R1 = 1 kΩ, R2 = 10 kΩ, C = 100 nF. t_H = 0,693 · 11 kΩ · 100 nF = 0,762 ms. t_L = 0,693 · 10 kΩ · 100 nF = 0,693 ms. T = 1,455 ms, f ≈ 687 Hz, Tastverhältnis = 0,762 / 1,455 ≈ 52 %.\n\nAm Oszilloskop lassen sich t_H und t_L direkt ablesen ([[ger-oszi|Oszilloskop]]). Siehe [[bg-timer-555|Timer 555]] und [[bg-astabil|astabile Kippstufe]].","verweise":["ger-oszi","bg-timer-555","bg-astabil"],"labs":["digi","mess"],"stich":["555","astabil","Frequenz","Tastverhältnis"],"pruef":3,"formeln":[{"text":"t_H = 0,693 · (R1 + R2) · C"},{"text":"t_L = 0,693 · R2 · C"},{"text":"f = 1,44 / ((R1 + 2 · R2) · C)"},{"text":"Tastverhältnis = t_H / (t_H + t_L)"}],"status":"entwurf"},
  {"id":"fo-gleichstrommotor","kat":"formel","titel":"Gleichstrommotor: Spannung, Drehzahl, Drehmoment","kurz":"Beim Gleichstrommotor ist die Klemmenspannung die Summe aus induzierter Spannung und Spannungsabfall am Ankerwiderstand. Die Drehzahl folgt aus der Spannung, das Moment aus dem Ankerstrom.","lang":"**Gleichungen**\n\n- Im Motorbetrieb: Die zugeführte Spannung U deckt die induzierte Spannung U_i und den Spannungsabfall I_A · R_A.\n- Die induzierte Spannung ist proportional zu Fluss und Drehzahl.\n- Das innere Drehmoment ist proportional zu Fluss und Ankerstrom.\n- Die Drehzahl folgt aus der Spannungsgleichung: mehr Spannung, mehr Drehzahl, bei Last sinkt sie etwas ab (Spannungsabfall am Anker).\n\n**Bauarten und Drehzahlstellung**\n\n- Fremderregt und Nebenschluss: Drehzahl fast lastunabhängig.\n- Reihenschluss: Drehzahl sinkt mit der Last, im Leerlauf kann sie gefährlich ansteigen, deshalb nur an Last betreiben.\n- Stellen der Drehzahl durch Ankerspannung (verlustarm), Vorwiderstand (verlustbehaftet) oder Feldschwächung.\n\n**Weitere Begriffe**\n\nKommutator (Stromwender) und Kohlebürsten, Wendepole und Kompensationswicklung gegen Ankerrückwirkung und Bürstenfeuer. Die Ankerspannung wird heute oft per [[fo-pwm-tastgrad|PWM]] gestellt. Bauteil: [[bt-motor|Motor]].","formeln":[{"text":"U = U_i + I_A · R_A"},{"text":"U_i = c · Φ · n"},{"text":"M_i = c · Φ · I_A / (2π)"},{"text":"n = (U − I_A · R_A) / (c · Φ)"}],"verweise":["fo-pwm-tastgrad","bt-motor"],"labs":["reg","sch"],"stich":["Gleichstrommotor","Nebenschlussmotor","Reihenschlussmotor","Ankerspannung","Drehzahl","Kommutator"],"pruef":2,"status":"entwurf"},
  {"id":"fo-hex-dual","kat":"formel","titel":"Hexadezimal und Dual","kurz":"Eine Hexadezimalziffer (0 bis 9, A bis F) entspricht genau vier Dualstellen. Daher lässt sich jedes Byte mit zwei Hexziffern schreiben.","lang":"Zuordnung: A = 10, B = 11, C = 12, D = 13, E = 14, F = 15. Gruppiere die Dualzahl von rechts in Vierergruppen (Tetraden) und ersetze jede durch eine Hexziffer.\n\nBeispiel (Übungswert): 0101 1011 = 5B. Dezimal ist das 5 · 16 + 11 = 91. Weiter: 14 dezimal = E hex = 1110 dual; 100 dezimal = 64 hex; 250 dezimal = FA hex.\n\nHex-Schreibweise ist kürzer und fehlerärmer als lange Dualzahlen. Sie wird für Adressen und Maschinencodes verwendet (z. B. 8-Bit-Adresse eines Ausgabebausteins, 16-Bit-Speicheradresse). Basis: [[fo-dual-dezimal|Dual nach Dezimal]]. Einsatz: [[bg-assembler|Assembler]] und [[bg-bussystem|Bussystem]].","verweise":["fo-dual-dezimal","bg-assembler","bg-bussystem"],"labs":["digi","code"],"stich":["Hexadezimal","Hex","Tetrade","Zahlensystem"],"pruef":3,"formeln":[{"text":"1 Hexziffer = 4 Bit"},{"text":"5B₁₆ = 0101 1011₂ = 91₁₀"}],"status":"entwurf"},
  {"id":"fo-555-monoflop","kat":"formel","titel":"Impulsdauer des 555 (monostabil)","kurz":"Im monostabilen Betrieb des 555 beträgt die Impulsdauer T = 1,1 · R · C. Sie hängt nur von Widerstand und Kondensator ab.","lang":"Der Kondensator lädt über R bis zu zwei Dritteln der Betriebsspannung. Dafür braucht er das 1,1-fache der Zeitkonstanten (genau ln 3 = 1,0986). Die Dauer ist praktisch unabhängig von der Betriebsspannung.\n\nBeispiel (Übungswert): R = 100 kΩ, C = 10 µF: T = 1,1 · 100 000 Ω · 0,000 01 F = 1,1 s. Mit R = 10 kΩ und C = 10 µF wären es 0,11 s.\n\nUmstellen: R = T / (1,1 · C). Für T = 0,5 s und C = 10 µF folgt R = 45,5 kΩ, nächster E12-Wert 47 kΩ. Beschreibung: [[bg-timer-555|Timer 555]], [[bg-monoflop|Monoflop]]; Bauteile: [[bt-r|Widerstand]], [[bt-c|Kondensator]].","verweise":["bg-timer-555","bg-monoflop","bt-r","bt-c"],"labs":["digi","sim"],"stich":["555","Monoflop","Impulsdauer","Zeitkonstante"],"pruef":3,"formeln":[{"text":"T = 1,1 · R · C"},{"text":"R = T / (1,1 · C)"}],"status":"entwurf"},
  {"id":"nw-ip-kennziffern","kat":"norm","titel":"IP-Kennziffern","kurz":"Die erste Kennziffer des IP-Codes (0 bis 6) beschreibt den Schutz gegen Berührung und Fremdkörper, die zweite (0 bis 9) den Schutz gegen Wasser.","lang":"**Erste Kennziffer** (feste Körper)\n\n- 0: kein Schutz\n- 1: Fremdkörper ab 50 mm\n- 2: Fremdkörper ab 12,5 mm, Finger\n- 3: ab 2,5 mm, Werkzeug\n- 4: ab 1 mm, Draht\n- 5: staubgeschützt\n- 6: staubdicht\n\n**Zweite Kennziffer** (Wasser)\n\n- 0: kein Schutz\n- 1: senkrecht tropfendes Wasser\n- 2: Tropfwasser bei 15° Neigung\n- 3: Sprühwasser\n- 4: allseitiges Spritzwasser\n- 5: Strahlwasser\n- 6: starkes Strahlwasser\n- 7: zeitweiliges Untertauchen\n- 8: dauerndes Untertauchen\n- 9: Hochdruck- und Dampfstrahlreinigung\n\nBeispiele: IP 20 ist ein Gehäuse für Innenräume mit Fingerschutz, IP 44 hat Draht- und Spritzwasserschutz, IP 54 ist staubgeschützt und spritzwassergeschützt, IP 65 ist staubdicht und strahlwassergeschützt, IP 67 ist staubdicht und tauchfähig. Siehe [[bg-ip-schutzart|IP-Schutzart]] und [[bg-schutzklassen|Schutzklassen]].","verweise":["bg-ip-schutzart","bg-schutzklassen"],"labs":["els","haus","pcb"],"stich":["IP 20","IP 44","IP 54","IP 65","IP 67","Schutzart","Fremdkörperschutz"],"pruef":2,"status":"entwurf"},
  {"id":"fo-kondensator","kat":"formel","titel":"Kapazität, Ladung und Zeitkonstante","kurz":"Die Kapazität eines Plattenkondensators ist C = ε₀ · εr · A / d. Ladung und Spannung hängen über Q = C · U zusammen, das Laden über einen Widerstand folgt der Zeitkonstante τ = R · C.","lang":"**Plattenkondensator**: C = ε₀ · εr · A / d mit der Feldkonstante ε₀ ≈ 8,854 · 10⁻¹² As/(Vm), der Permittivitätszahl εr des Dielektrikums, Plattenfläche A und Plattenabstand d.\n\nÜbungswert: A = 40 cm² (4 · 10⁻³ m²), d = 1 mm, εr = 2,1 (Kunststoff) ergibt etwa 74 pF.\n\n**Ladung** Q = C · U, Übungswert: 10 µF bei 60 V speichern 600 µC.\n\n**Schaltungen**: Parallel addieren sich die Kapazitäten, C_ges = C₁ + C₂ + …. In Reihe addieren sich die Kehrwerte, 1/C_ges = 1/C₁ + 1/C₂ + …; Übungswert: 10 µF in Reihe mit 40 µF ergeben 8 µF, parallel 50 µF.\n\n**Laden über Widerstand**: τ = R · C. Nach 5 τ ist der Kondensator zu etwa 99 % geladen. Übungswert: R = 1 MΩ, C = 10 µF ergibt τ = 10 s, nach etwa 50 s ist er praktisch voll.\n\nHintergrund unter [[bg-elektrisches-feld|elektrisches Feld und Kondensator]]; Bauteile [[bt-c|Kondensator]], [[bt-ce|Elko]]. Im Wechselstromkreis siehe [[fo-blindwiderstand|kapazitiver Blindwiderstand]].","verweise":["bg-elektrisches-feld","bt-c","bt-ce","fo-blindwiderstand"],"labs":["sim","wsl","mess"],"stich":["Kapazität","Zeitkonstante","Tau","Plattenkondensator","Permittivität","Ladekurve","RC-Glied"],"pruef":3,"status":"entwurf","formeln":[{"text":"C = ε₀ · εr · A / d"},{"text":"Q = C · U"},{"text":"τ = R · C"}]},
  {"id":"fo-koerperstrom","kat":"formel","titel":"Körperstrom und Berührungsspannung","kurz":"Der Körperstrom ergibt sich aus der Berührungsspannung und dem Gesamtwiderstand des Stromwegs: I_K = U / R_ges. Die Berührungsspannung am Körper ist U_B = R_K · I_K.","lang":"Der Stromweg besteht aus mehreren Widerständen in Reihe: Fehlerstelle R_F, Körper R_K (Übergangs- und Innenwiderstände), Standort R_x (zum Beispiel isolierender Boden) und Erdübergang R_E. Es gilt R_ges = R_F + R_K + R_x + R_E, I = U / R_ges und U_B = R_K · I.\n\nÜbungswert 1: Person mit R_K = 1 kΩ berührt 230 V direkt: I = 230 mA, weit über der Gefahrengrenze.\n\nÜbungswert 2: R_F = 400 Ω, R_K = 1 kΩ, R_x = 5 kΩ, R_E = 10 Ω ergibt R_ges = 6410 Ω, I ≈ 35,9 mA, U_B ≈ 35,9 V.\n\nRichtwerte der Ausbildung: gefährlich sind Wechselströme ab etwa 50 mA und Berührungsspannungen über 50 V AC oder 120 V DC. Die tatsächliche Gefahr hängt von Dauer, Weg und Frequenz ab.\n\nSiehe [[bg-beruehrungsspannung|Berührungsspannung und Körperstrom]] und [[bt-rcd|RCD]].","verweise":["bg-beruehrungsspannung","bt-rcd"],"labs":["els","haus"],"stich":["Körperstrom","Berührungsspannung","Körperwiderstand","Fehlerstrom","Standortwiderstand"],"pruef":3,"status":"entwurf","formeln":[{"text":"R_ges = R_F + R_K + R_x + R_E"},{"text":"I_K = U / R_ges"},{"text":"U_B = R_K · I_K"}]},
  {"id":"fo-kv-bloecke","kat":"formel","titel":"KV-Diagramm: Felder und Blockregeln","kurz":"Ein KV-Diagramm mit n Variablen hat 2ⁿ Felder. Ein Block aus 2ᵏ benachbarten Einsen spart k Variablen in der Gleichung.","lang":"Zahl der Felder: 2 Variablen: 4 Felder, 3 Variablen: 8, 4 Variablen: 16.\n\nBlockgröße: 1, 2, 4, 8, ... Felder. Ein Block mit 2 Feldern lässt eine Variable wegfallen, mit 4 Feldern zwei, mit 8 Feldern drei.\n\nBeispiel (Übungswert): Bei vier Variablen D, C, B, A bilden die vier Felder mit B = 1 und A = 1 einen Block (D und C ändern sich darin). Das Ergebnis ist B UND A, also zwei Variablen weniger.\n\nVorgehen: Alle Einsen abdecken, möglichst große Blöcke, Überlappung erlaubt, Randfelder gelten als Nachbarn. Details und Hintergrund: [[bg-kv-diagramm|KV-Diagramm]]. Die ungekürzte Form liefert die [[bg-normalform|Normalform]].","verweise":["bg-kv-diagramm","bg-normalform"],"labs":["digi"],"stich":["KV","Block","Felder","Vereinfachen"],"pruef":3,"formeln":[{"text":"Felder = 2ⁿ"},{"text":"Block mit 2ᵏ Feldern spart k Variablen"}],"status":"entwurf"},
  {"id":"nw-leiterfarben","kat":"norm","titel":"Leiterfarben und Kennzeichnung","kurz":"Die Aderfarben sind festgelegt: L1 braun, L2 schwarz, L3 grau, N blau, PE grün-gelb, PEN grün-gelb mit blauen Enden. Betriebsmittel haben Kennbuchstaben, zum Beispiel M für Motor.","lang":"**Aderfarben im Drehstromnetz**\n\n- L1: braun\n- L2: schwarz\n- L3: grau\n- N (Neutralleiter): blau\n- PE (Schutzleiter): grün-gelb\n- PEN: grün-gelb mit blauen Enden\n\n**Kennbuchstaben** von Betriebsmitteln im Schaltplan (Beispiele): A Baugruppen und Schaltgeräte, M Motor, P Meldeleuchte, Q Schütz oder Leistungsschalter, T Transformator, X Klemmen und Verbindungsstellen.\n\nDie Bedeutung der Leiter findest du bei [[bg-leiterarten|Leiterarten]], die Netzformen bei [[bg-netzsysteme|Netzsysteme]]. Schaltzeichen sind nach DIN EN 60617 genormt.","verweise":["bg-leiterarten","bg-netzsysteme"],"labs":["haus","els","sch"],"stich":["Aderfarbe","Leiterkennzeichnung","grün-gelb","Kennbuchstaben","Betriebsmittelkennzeichnung"],"pruef":3,"status":"entwurf"},
  {"id":"fo-widerstand-leiter","kat":"formel","titel":"Leiterwiderstand und Temperaturabhängigkeit","kurz":"Der Widerstand eines Drahts wächst mit seiner Länge und dem spezifischen Widerstand und sinkt mit dem Querschnitt. Metalle werden bei Erwärmung hochohmiger, ΔR = α · R₂₀ · Δϑ.","lang":"**Leiterwiderstand** R = ρ · l / A mit dem spezifischen Widerstand ρ in Ω·mm²/m, der Länge l in m und dem Querschnitt A in mm². Richtwerte: Kupfer etwa 0,0178 Ω·mm²/m, Aluminium etwa 0,0278 Ω·mm²/m.\n\nÜbungswert: Eine Kupferleitung hat 40 m Hinweg und 40 m Rückweg, also l = 80 m, A = 1,5 mm². R = 0,0178 · 80 / 1,5 ≈ 0,95 Ω. Bei 10 A fällt auf der Leitung ΔU = R · I ≈ 9,5 V ab, die Verlustleistung beträgt P = R · I² ≈ 95 W. Deshalb brauchen lange Leitungen mehr Querschnitt.\n\n**Temperatur**: R_ϑ = R₂₀ + ΔR mit ΔR = α · R₂₀ · Δϑ und der Temperaturdifferenz Δϑ in K. Für Kupfer ist α etwa 0,0039 1/K (Übungswert). Beispiel: R₂₀ = 100 Ω, Δϑ = 40 K ergibt ΔR = 15,6 Ω, also 115,6 Ω bei 60 °C. Bei Heißleitern (NTC) ist α negativ, bei Kaltleitern (PTC) stark positiv. Zum Widerstand als Bauteil siehe [[bt-r|Widerstand]], [[bt-ntc|Heißleiter]], [[bt-ptc|Kaltleiter]]. Reihen- und Parallelschaltung: [[fo-reihe-parallel|Reihe und Parallel]].","verweise":["bt-r","bt-ntc","bt-ptc","fo-reihe-parallel"],"labs":["sim","haus","thm"],"stich":["spezifischer Widerstand","ρ","Temperaturkoeffizient","Leitungswiderstand","Kupfer","Leitungsverlust"],"pruef":3,"status":"entwurf","formeln":[{"text":"R = ρ · l / A"},{"text":"ΔR = α · R₂₀ · Δϑ"},{"text":"R_ϑ = R₂₀ + ΔR"}]},
  {"id":"fo-messabweichung","kat":"formel","titel":"Messabweichung analog und digital","kurz":"Bei Digitalgeräten gilt F = ±(z % vom Messwert + n Digit), bei Analoggeräten F = ±Klasse % vom Messbereichsendwert. So bestimmst du den Bereich, in dem der wahre Wert liegt.","lang":"**Digital**: F = ±(z / 100 · M + n · Auflösung). Der wahre Wert liegt zwischen M − F und M + F.\n\nÜbungswert: Anzeige M = 12,50 V, Angabe ±(0,5 % v. Mw. + 2 Digit), Auflösung 0,01 V. F = 0,0625 V + 0,02 V ≈ 0,08 V, der wahre Wert liegt zwischen 12,42 V und 12,58 V.\n\n**Analog**: Die Klasse bezieht sich auf den Messbereichsendwert: F = ±Klasse / 100 · M_End. Übungswert: Klasse 1,5, Bereich 100 V gibt F = ±1,5 V an jeder Stelle der Skala. Bei Anzeige 40 V sind das 3,75 % vom Messwert, deshalb soll der Zeiger im oberen Skalenteil stehen.\n\n**Belastung durch das Messgerät**: Der Innenwiderstand des Spannungsmessers liegt parallel zum Messobjekt, der des Strommessers in Reihe. Systematische Schaltungsfehler (stromrichtig oder spannungsrichtig) vermeidest du durch die richtige Schaltung.\n\nSiehe [[bg-messtechnik-begriffe|Messtechnik]], [[bd-dmm-genauigkeit|Genauigkeit des Multimeters]], [[ger-dmm|Multimeter]].","verweise":["bg-messtechnik-begriffe","bd-dmm-genauigkeit","ger-dmm"],"labs":["mess","sim"],"stich":["Fehlergrenze","Genauigkeit","Digit","Klassengenauigkeit","Messunsicherheit","Ablesefehler"],"pruef":3,"status":"entwurf","formeln":[{"text":"F = ±(z/100 · M + n · Auflösung)"},{"text":"F = ±Klasse/100 · M_End"}]},
  {"id":"fo-statistik-kennwerte","kat":"formel","titel":"Mittelwert, Spannweite und Standardabweichung","kurz":"Mittelwert, Spannweite und Standardabweichung beschreiben, wo eine Messreihe liegt und wie stark sie streut. Sie sind die Grundlage von Regelkarten und Prozessfähigkeit.","lang":"**Kennwerte einer Messreihe mit n Werten**\n\n- Mittelwert: Summe aller Werte geteilt durch ihre Anzahl.\n- Spannweite R: größter Wert minus kleinster Wert (schnell zu berechnen, aber nur von zwei Werten abhängig).\n- Standardabweichung s: typische Abweichung der Werte vom Mittelwert. Bei einer Stichprobe wird durch n − 1 geteilt.\n\n**Beispiel**\n\nFünf Messungen einer Spannung: 4,98 V, 5,01 V, 5,00 V, 5,03 V, 4,98 V. Mittelwert 5,00 V, Spannweite 0,05 V.\n\n**Verwendung**\n\nIn der Qualitätsregelkarte ([[bg-qualitaetswerkzeuge|Q7]]) werden Mittelwert und Streuung über der Zeit aufgetragen. Das [[ger-dmm|Multimeter]] liefert die Einzelwerte. Daraus folgt die [[fo-prozessfaehigkeit|Prozessfähigkeit]].","formeln":[{"text":"x̄ = (x₁ + x₂ + … + xₙ) / n"},{"text":"R = x_max − x_min"},{"text":"s = √( Σ (xᵢ − x̄)² / (n − 1) )"}],"verweise":["bg-qualitaetswerkzeuge","ger-dmm","fo-prozessfaehigkeit"],"labs":["pr","mess"],"stich":["Mittelwert","Standardabweichung","Spannweite","Streuung","Stichprobe"],"pruef":2,"status":"entwurf"},
  {"id":"fo-glaettung","kat":"formel","titel":"Netzteil: Spitzenwert und Brummspannung","kurz":"Hinter dem Brückengleichrichter lädt sich der Siebkondensator auf etwa den Spitzenwert abzüglich zweier Diodenspannungen. Die Welligkeit ist näherungsweise ΔU ≈ I_L / (f_B · C).","lang":"**Ladespannung**: U_C ≈ û_Sek − 2 · U_F (Brückenschaltung, zwei Dioden leiten). Übungswert: Sekundär 12 V effektiv, û ≈ 17 V, U_F ≈ 0,7 V je Diode, also etwa 15,6 V.\n\n**Brummfrequenz**: Bei Einweggleichrichtung f_B = f (50 Hz), bei der Brückenschaltung f_B = 2 · f = 100 Hz.\n\n**Welligkeit** (Näherung): ΔU ≈ I_L / (f_B · C). Übungswert: I_L = 0,5 A, f_B = 100 Hz, C = 2200 µF ergibt ΔU ≈ 2,3 V. Mehr Kapazität oder weniger Laststrom verringern die Welligkeit.\n\nDie Brummspannung wird anschließend durch Siebung und Stabilisierung verkleinert. Siehe [[bg-netzteilarten|Netzteil]], [[bt-bruecke|Brückengleichrichter]], [[bt-ce|Elko]], [[bt-trf|Transformator]].","verweise":["bg-netzteilarten","bt-bruecke","bt-ce","bt-trf"],"labs":["nts","sim","enr"],"stich":["Brummspannung","Welligkeit","Siebkondensator","Ladekondensator","B2U","Glättungskondensator"],"pruef":3,"status":"entwurf","formeln":[{"text":"ΔU ≈ I_L / (f_B · C)"},{"text":"U_C ≈ û − 2 · U_F"}]},
  {"id":"fo-prozentrechnung","kat":"formel","titel":"Prozentrechnung","kurz":"Prozent heißt „von Hundert“. Aus Grundwert, Prozentwert und Prozentsatz lässt sich bei zwei bekannten Größen die dritte berechnen. Typisch sind Toleranzen, Rabatte, Skonto und Ausschuss.","lang":"**Die drei Größen**\n\n- Grundwert G: der Ganze (100 Prozent)\n- Prozentwert W: der betrachtete Anteil\n- Prozentsatz p: der Anteil in Prozent\n\n**Beispiele**\n\n- Skonto: 3 Prozent auf 800 € Rechnungsbetrag sind 800 · 3 / 100 = 24 €.\n- Toleranz: Ein Widerstand mit 5 Prozent Toleranz und 1000 Ω darf zwischen 950 Ω und 1050 Ω liegen.\n- Anteil: 12 von 400 Teilen sind 3 Prozent ([[fo-ausschussquote|Ausschussquote]]).\n\n**Merkhilfe**\n\nProzentwert ist Grundwert mal Prozentsatz geteilt durch 100. Bei Auf- und Abschlägen immer überlegen, auf welchen Grundwert sich die Prozente beziehen. Das zählt auch bei der [[fo-messabweichung|relativen Messabweichung]].","formeln":[{"text":"W = G · p / 100"},{"text":"p = W / G · 100 %"},{"text":"G = W · 100 / p"}],"verweise":["fo-ausschussquote","fo-messabweichung"],"labs":["pr","sch"],"stich":["Prozent","Prozentwert","Grundwert","Prozentsatz","Skonto","Rabatt"],"pruef":2,"status":"entwurf"},
  {"id":"fo-prozessfaehigkeit","kat":"formel","titel":"Prozessfähigkeit (Cp und Cpk)","kurz":"Cp und Cpk vergleichen die Streuung eines Fertigungsprozesses mit den Toleranzgrenzen. Cp ist die mögliche Fähigkeit bei zentriertem Prozess, Cpk berücksichtigt zusätzlich die Lage des Mittelwerts.","lang":"**Grundidee**\n\nEin Prozess ist fähig, wenn seine Streuung (gemessen in Standardabweichungen σ) deutlich schmaler ist als der erlaubte Bereich zwischen unterer und oberer Toleranzgrenze (USG und OSG).\n\n- Cp: Verhältnis von Toleranzbreite zu 6σ. Sagt, ob der Prozess prinzipiell genau genug wäre.\n- Cpk: Abstand des Mittelwerts zur näheren Grenze, geteilt durch 3σ. Sagt, ob er es mit seiner aktuellen Lage auch ist. Cpk ist nie größer als Cp.\n\n**Beurteilung**\n\nAls Faustwert gilt in vielen Betrieben ein Prozess bei Cpk von mindestens 1,33 als fähig. Je größer, desto sicherer. Unter 1,00 liegt ein Teil der Produktion außerhalb der Toleranz.\n\n**Beispiel**\n\nEin Widerstand soll 100 Ω haben, erlaubt sind 99 bis 101 Ω. Gemessen werden Mittelwert 100,0 Ω und σ = 0,2 Ω. Dann ist Cp = 2 / 1,2 ≈ 1,67; der Prozess liegt mittig, also ist Cpk ebenfalls 1,67.\n\nDie Messwerte kommen aus [[bg-pruefmittel|geprüften Messmitteln]]. Mittelwert und Streuung beschreibt [[fo-statistik-kennwerte|Statistik-Kennwerte]]. Überwacht wird der Prozess mit einer [[bg-qualitaetswerkzeuge|Qualitätsregelkarte]].","formeln":[{"text":"Cp = (OSG − USG) / (6 · σ)"},{"text":"Cpk = min( (OSG − x̄) / (3 · σ) ; (x̄ − USG) / (3 · σ) )"}],"verweise":["bg-pruefmittel","fo-statistik-kennwerte","bg-qualitaetswerkzeuge"],"labs":["pr","mess"],"stich":["Cp","Cpk","Prozessfähigkeit","Maschinenfähigkeit","Sigma","Toleranz"],"pruef":2,"status":"entwurf"},
  {"id":"fo-pwm-tastgrad","kat":"formel","titel":"PWM: Tastgrad und Mittelwert","kurz":"Bei der Pulsweitenmodulation bleibt die Periodendauer gleich, die Impulsbreite ändert sich. Der Tastgrad ist Einschaltzeit durch Periodendauer; er bestimmt den Mittelwert der Spannung.","lang":"**Prinzip**\n\nEin Schalter (zum Beispiel ein [[bt-npn|Transistor]]) schaltet die Spannung schnell ein und aus. Das Verhältnis von Einschaltzeit zur Periodendauer heißt Tastgrad D (oder Tastverhältnis). Bei D = 0,5 ist die Spannung die Hälfte der Zeit da.\n\n**Mittelwert**\n\nDer Mittelwert ist der Tastgrad mal die Spannung während der Einschaltzeit. Bei 12 V und D = 0,25 ergibt sich im Mittel 3 V. So lassen sich Motordrehzahl, Helligkeit einer Leuchtdiode oder ein Spulenstrom ohne Verlustwiderstand steuern.\n\n**Hinweise**\n\n- Die Taktfrequenz wird oft oberhalb des hörbaren Bereichs gewählt, weil Spulen und Wicklungen sonst hörbar schwingen können.\n- Eine Freilaufdiode schützt den Schalter, wenn eine Spule abgeschaltet wird.\n- Für die Stromregelung wird der Stellwert aus Sollwert und Istwert gebildet, oft mit einem PI-Regler.\n\nSiehe auch [[bt-motor|Motor]] und [[fo-gleichstrommotor|Gleichstrommotor]].","formeln":[{"text":"D = t_ein / T"},{"text":"U_mittel = D · U_ein"},{"text":"f = 1 / T"}],"verweise":["bt-npn","bt-motor","fo-gleichstrommotor"],"labs":["sch","reg","mess"],"stich":["PWM","Pulsweitenmodulation","Tastgrad","Tastverhältnis","Duty Cycle"],"pruef":2,"status":"entwurf"},
  {"id":"fo-reihe-parallel","kat":"formel","titel":"Reihen- und Parallelschaltung, Spannungsteiler","kurz":"In der Reihenschaltung addieren sich die Widerstände und die Spannungen verteilen sich im Verhältnis der Widerstände. In der Parallelschaltung addieren sich die Leitwerte, der Gesamtwiderstand ist kleiner als der kleinste Einzelwiderstand.","lang":"**Reihenschaltung**: gleicher Strom durch alle Widerstände, R_ges = R₁ + R₂ + …, die Teilspannungen verhalten sich wie die Widerstände: U₁ / U₂ = R₁ / R₂ (Spannungsteiler).\n\nÜbungswert: 1 kΩ und 2 kΩ an 12 V: I = 12 V / 3 kΩ = 4 mA, U₂ = 2 kΩ · 4 mA = 8 V. Mit R₁ = 200 Ω, R₂ = 300 Ω an 30 V: I = 60 mA, U₁ = 12 V, U₂ = 18 V.\n\n**Parallelschaltung**: gleiche Spannung an allen Zweigen, 1/R_ges = 1/R₁ + 1/R₂ + …, oder mit Leitwerten G_ges = G₁ + G₂ + …. Für zwei Widerstände R_ges = R₁ · R₂ / (R₁ + R₂). Die Teilströme verhalten sich umgekehrt wie die Widerstände. Übungswert: 24 Ω parallel 36 Ω ergibt 14,4 Ω.\n\n**Gemischte Schaltungen** löst du schrittweise: Teilgruppen zusammenfassen, bis ein Gesamtwiderstand bleibt, dann rückwärts Ströme und Spannungen verteilen.\n\n**Kirchhoffsche Regeln**: Die Summe der Ströme in einem Knoten ist null, die Summe der Spannungen in einer Masche ist null. Bauteil: [[bt-r|Widerstand]], [[bt-pot|Potentiometer]] als einstellbarer Spannungsteiler. Zur Arbeitsgeraden siehe [[fo-arbeitsgerade|Arbeitsgerade]].","verweise":["bt-r","bt-pot","fo-arbeitsgerade"],"labs":["sim","sch","mess"],"stich":["Reihenschaltung","Parallelschaltung","Spannungsteiler","Stromteiler","Kirchhoff","Knotenregel","Maschenregel","Gesamtwiderstand"],"pruef":3,"status":"entwurf","formeln":[{"text":"R_ges = R₁ + R₂ + …"},{"text":"1/R_ges = 1/R₁ + 1/R₂ + …"},{"text":"U₁ / U₂ = R₁ / R₂"}]},
  {"id":"nw-ttl-pegel","kat":"norm","titel":"Richtwerte Standard-TTL (74er-Reihe)","kurz":"Typische Datenblattwerte der Standard-TTL-Familie bei 5 V: Pegelgrenzen, zulässige Ströme und Fan-out. Maßgeblich bleibt immer das Datenblatt des verwendeten Bausteins.","lang":"Richtwerte Standard-TTL (Übungswerte, Datenblatt beachten):\n- Versorgung: 5 V\n- U_IL(max), Eingang noch L: 0,8 V\n- U_IH(min), Eingang schon H: 2,0 V\n- U_OL(max), Ausgang L: 0,4 V\n- U_OH(min), Ausgang H: 2,4 V\n- I_IL (je Eingang bei L, fließt aus dem Eingang): 1,6 mA\n- I_IH (je Eingang bei H): 40 µA\n- I_OL(max): 16 mA\n- I_OH(max): 0,4 mA\n- Fan-out: 10\n- Unbeschalteter Eingang: wirkt wie H\n- Gegentaktausgang: nicht parallel schalten","verweise":["bg-ttl","bg-pegelbereiche","bg-lastfaktoren"],"labs":["digi"],"stich":["TTL","Pegel","Datenblatt","7400"],"pruef":3,"status":"entwurf"},
  {"id":"fo-schleifendurchlaeufe","kat":"formel","titel":"Schleifendurchläufe zählen","kurz":"Eine for-Schleife mit Start, Obergrenze und Schrittweite läuft so oft, wie die Bedingung erfüllt ist. Zählen Sie die Werte der Zählvariablen, für die die Bedingung wahr bleibt.","lang":"Beispiel (Übungswert): for (i = 0; i < 5; i++) läuft für i = 0, 1, 2, 3, 4 und damit 5 Mal. for (i = 1; i <= 10; i += 3) läuft für i = 1, 4, 7, 10, also 4 Mal. for (i = 10; i > 0; i -= 2) läuft für 10, 8, 6, 4, 2, also 5 Mal.\n\nAllgemein, bei Bedingung i < Ende und positiver Schrittweite: Durchläufe = Aufrundung von (Ende − Start) / Schritt. Bei i <= Ende zählt der Endwert mit, falls er getroffen wird.\n\nEine do-while-Schleife läuft mindestens einmal, eine while-Schleife eventuell nie. In einer Zeitschleife wird dagegen ein Zähler heruntergezählt, bis er null erreicht (Zero-Flag). Siehe [[bg-schleifen|Schleifen]] und [[bg-assembler|Assembler]].","verweise":["bg-schleifen","bg-assembler"],"labs":["code"],"stich":["for","Schleife","Durchläufe","Zählvariable"],"pruef":3,"formeln":[{"text":"Durchläufe = ⌈(Ende − Start) / Schritt⌉ (Bedingung i < Ende)"}],"status":"entwurf"},
  {"id":"fo-seriell-rate","kat":"formel","titel":"Serielle Übertragungsrate","kurz":"Bei asynchroner serieller Übertragung kostet jedes Zeichen mehr Bits als nur die Daten: Startbit, Datenbits und Stoppbit(s). Aus der Baudrate folgen Bitzeit und Zeichenrate.","lang":"Ein häufiges Format ist 8N1: 1 Startbit, 8 Datenbits, keine Parität, 1 Stoppbit, also 10 Bit je Zeichen.\n\nBeispiel (Übungswert): Baudrate 9600 Bit/s. Bitzeit = 1 / 9600 s ≈ 104 µs. Zeichenrate = 9600 / 10 = 960 Zeichen/s. Für 1000 Zeichen braucht man etwa 1,04 s. Die reine Datenrate ist 960 · 8 = 7680 Bit/s.\n\nSender und Empfänger müssen dieselbe Baudrate eingestellt haben, weil sie getrennte Taktgeber besitzen. Mehr: [[bg-serielle-uebertragung|serielle Übertragung]] und [[bg-mikrocontroller|Mikrocontroller]].","verweise":["bg-serielle-uebertragung","bg-mikrocontroller"],"labs":["code","digi"],"stich":["Baudrate","Startbit","Stoppbit","8N1"],"pruef":3,"formeln":[{"text":"t_Bit = 1 / Baudrate"},{"text":"Zeichen/s = Baudrate / Bits je Zeichen"}],"status":"entwurf"},
  {"id":"fo-speicherkapazitaet","kat":"formel","titel":"Speicherkapazität und Adressleitungen","kurz":"Mit n Adressleitungen sind 2ⁿ Speicherstellen ansprechbar. Die Kapazität ergibt sich aus der Zahl der Stellen mal der Wortbreite.","lang":"Beispiel (Übungswert): 10 Adressleitungen adressieren 1024 Stellen. 16 Adressleitungen adressieren 65 536 Stellen. Bei 8 Bit Wortbreite sind das 65 536 Byte, also 64 KiB (1 KiB = 1024 Byte).\n\nKapazität in Bit = Zahl der Stellen · Wortbreite in Bit. Ein Speicher mit 2048 Stellen zu 8 Bit hat 16 384 Bit, also 2 KiB. Soll ein Speicher 4096 Stellen haben, braucht er 12 Adressleitungen, weil 2 hoch 12 gleich 4096 ist.\n\nDie Adressleitungen gehören zum Adressbus ([[bg-bussystem|Bussystem]]). Mit einem Adressdecoder wird aus der Adresse die Auswahl einer Zeile oder eines Bausteins ([[bg-speicherarten|Halbleiterspeicher]]). Rechenhilfe: [[fo-wertebereich|Wertebereich bei n Bit]].","verweise":["bg-bussystem","bg-speicherarten","fo-wertebereich"],"labs":["digi","code"],"stich":["Speicherkapazität","Adressleitung","KiB","Adressraum"],"pruef":3,"formeln":[{"text":"Stellen = 2ⁿ"},{"text":"Kapazität = Stellen · Wortbreite"}],"status":"entwurf"},
  {"id":"fo-sperrschichttemperatur","kat":"formel","titel":"Sperrschichttemperatur und Kühlkörper","kurz":"Die Sperrschichttemperatur ist die Umgebungstemperatur plus Verlustleistung mal Summe der Wärmewiderstände: ϑ_j = ϑ_U + P_V · (R_thJC + R_thCK + R_thKA).","lang":"Die Wärme fließt von der Sperrschicht (j) zum Gehäuse (C), vom Gehäuse zum Kühlkörper (K) und vom Kühlkörper in die Umgebung (A/U). Die Wärmewiderstände in K/W addieren sich, die Temperaturdifferenz ist Verlustleistung mal Gesamtwiderstand.\n\nϑ_j = ϑ_U + P_V · (R_thJC + R_thCK + R_thKA).\n\nÜbungswert: P_V = 5 W, ϑ_U = 40 °C, R_thJC = 2 K/W, R_thCK = 0,5 K/W, R_thKA = 4 K/W. Gesamt 6,5 K/W, Erwärmung 32,5 K, also ϑ_j = 72,5 °C, weit unter dem Richtwert 150 °C für Silizium.\n\nUmgekehrt bestimmst du den nötigen Kühlkörper: R_thKA ≤ (ϑ_j,zul − ϑ_U) / P_V − R_thJC − R_thCK. Mit einer Reserve rechnest du etwa mit ϑ_j,zul = 125 °C: (85 K / 5 W) − 2,5 K/W = 14,5 K/W.\n\nHintergrund: [[bg-kuehlung-halbleiter|Kühlung von Halbleitern]], Verlustleistung des [[bt-npn|Transistors]] im [[fo-basisvorwiderstand|Schaltbetrieb]].","verweise":["bg-kuehlung-halbleiter","bt-npn","fo-basisvorwiderstand"],"labs":["thm","nts","ana"],"stich":["Wärmewiderstand","R_th","Sperrschichttemperatur","Kühlkörperberechnung","Verlustleistung"],"pruef":2,"status":"entwurf","formeln":[{"text":"ϑ_j = ϑ_U + P_V · (R_thJC + R_thCK + R_thKA)"}]},
  {"id":"fo-teilerverhaeltnis","kat":"formel","titel":"Teilerverhältnis von Zählern","kurz":"Ein Zähler aus n Flipflop-Stufen teilt die Eingangsfrequenz durch 2ⁿ. Jede einzelne Stufe halbiert die Frequenz.","lang":"Die Ausgänge eines Dualzählers liefern f/2, f/4, f/8, f/16 und so weiter. Ein 4-Bit-Zähler hat Teilerverhältnis 16.\n\nBeispiel (Übungswert): Takt 8 kHz an einem 4-Bit-Zähler: QA = 4 kHz, QB = 2 kHz, QC = 1 kHz, QD = 500 Hz. Bei 500 Hz Takt liefert QD etwa 31,25 Hz.\n\nSoll ein Zähler schon vor dem Überlauf zurückgesetzt werden (z. B. Modulo 10), verkürzt sich die Zählfolge, und das Teilerverhältnis ist dann gleich dem Modul. Aufbau: [[bg-zaehler|Zähler]] und [[bg-ff-typen|Flipflops]]. Zusammenhang mit der Bitzahl: [[fo-wertebereich|Wertebereich]].","verweise":["bg-zaehler","bg-ff-typen","fo-wertebereich"],"labs":["digi"],"stich":["Frequenzteiler","Teilerverhältnis","Zähler","Modulo"],"pruef":3,"formeln":[{"text":"f_aus = f_ein / 2ⁿ"},{"text":"Zählumfang = 2ⁿ (Modulo)"}],"status":"entwurf"},
  {"id":"fo-trafo","kat":"formel","titel":"Transformator: Übersetzung und Wirkungsgrad","kurz":"Beim idealen Transformator verhalten sich die Spannungen wie die Windungszahlen und die Ströme umgekehrt. Der Wirkungsgrad ist abgegebene durch zugeführte Leistung.","lang":"**Übersetzung**: U₁ / U₂ = N₁ / N₂ = I₂ / I₁. Widerstände werden quadratisch übersetzt: Z₁ = (N₁ / N₂)² · Z₂.\n\n**Wirkungsgrad**: η = P_ab / P_zu = P_ab / (P_ab + P_Fe + P_Cu) mit Eisenverlusten P_Fe und Kupferverlusten P_Cu.\n\nÜbungswert: 230 V primär, 12 V sekundär, N₁ = 1150, N₂ = 60. Übersetzung ≈ 19,2. Bei I₂ = 2 A fließen primär ideal etwa 0,10 A. P_ab = 24 W; mit P_Fe = 1 W und P_Cu = 2 W ist η = 24 / 27 ≈ 89 %. Ein sekundärer Lastwiderstand von 6 Ω erscheint primär als etwa 2,2 kΩ.\n\nSiehe [[bt-trf|Transformator]], der Einsatz im [[bg-netzteilarten|Netzteil]]. Das Prinzip beruht auf [[bg-induktion|Induktion]].","verweise":["bt-trf","bg-netzteilarten","bg-induktion"],"labs":["nts","enr","wsl"],"stich":["Übersetzungsverhältnis","Windungszahl","Wirkungsgrad","Primärstrom","Sekundärspannung","Eisenverluste","Kupferverluste"],"pruef":3,"status":"entwurf","formeln":[{"text":"U₁ / U₂ = N₁ / N₂ = I₂ / I₁"},{"text":"Z₁ = (N₁ / N₂)² · Z₂"},{"text":"η = P_ab / P_zu"}]},
  {"id":"nw-arbeitsrecht-fristen","kat":"norm","titel":"Übersicht: Fristen und Zahlen im Arbeitsrecht","kurz":"Kompakte Übersicht der wichtigsten Fristen und Zahlen: Probezeit, Kündigungsfristen, Klagefrist, Arbeitszeit, Pausen, Ruhezeit, Mindesturlaub, Mutterschutz. Die Quelle der Regel steht dabei.","lang":"**Kündigung** ([[bg-kuendigung|Kündigung]])\n\n- Probezeit Arbeitsverhältnis: zwei Wochen Frist\n- danach Grundfrist: vier Wochen zum 15. oder zum Monatsende\n- Arbeitgeberfristen verlängern sich: 2 / 5 / 8 / 10 / 12 / 15 / 20 Jahre Betriebszugehörigkeit = 1 / 2 / 3 / 4 / 5 / 6 / 7 Monate zum Monatsende\n- Kündigungsschutzklage: drei Wochen nach Zugang\n- fristlos: innerhalb von zwei Wochen nach Kenntnis des Grundes\n- Sperrzeit Arbeitslosengeld nach Aufhebungsvertrag: bis zu zwölf Wochen\n\n**Ausbildung** ([[bg-berufsausbildung|Berufsausbildung]])\n\n- Probezeit: ein bis vier Monate, jederzeit ohne Frist kündbar\n- nach der Probezeit: Auszubildender mit vier Wochen Frist bei Ausbildungsabbruch oder Berufswechsel, Betrieb nur fristlos aus wichtigem Grund\n\n**Arbeitszeit** ([[bg-arbeitszeitgesetz|Arbeitszeit]])\n\n- acht Stunden je Werktag, bis zehn mit Ausgleich; höchstens 48 Stunden je Woche\n- Pause: 30 Minuten (mehr als 6 bis 9 Stunden), 45 Minuten (mehr als 9 Stunden)\n- Ruhezeit: elf Stunden; mindestens 15 freie Sonntage\n- Jugendliche: 8 Stunden am Tag, 40 in der Woche, Ruhezeit 12 Stunden\n\n**Urlaub** ([[bg-urlaubsanspruch|Urlaub]])\n\n- 24 Werktage = 20 Arbeitstage bei Fünf-Tage-Woche\n- Wartezeit sechs Monate\n- Jugendliche: 30 / 27 / 25 Werktage (unter 16 / 17 / 18 Jahren)\n\n**Schutz** ([[bg-kuendigungsschutz|Kündigungsschutz]])\n\n- Mutterschutz: sechs Wochen vor, acht Wochen nach der Geburt\n- Elternzeit: bis zu 36 Monate\n- Betriebsrat: Amtszeit plus ein Jahr\n\n**Wirtschaft**\n\n- Sozialwahl alle sechs Jahre; Verjährung von Mängelansprüchen zwei Jahre ([[bg-kaufvertrag|Kaufvertrag]])","verweise":["bg-kuendigung","bg-berufsausbildung","bg-arbeitszeitgesetz","bg-urlaubsanspruch","bg-kuendigungsschutz","bg-kaufvertrag"],"labs":["pr"],"stich":["Fristen","Kündigungsfristen","Arbeitsrecht","Mindesturlaub","Pausen","Probezeit","Übersicht"],"pruef":3,"status":"entwurf"},
  {"id":"nw-normreihen","kat":"norm","titel":"Übersicht: Normen, Richtlinien und Vorschriften","kurz":"Übersicht der im Beruf häufig genannten Normen und Vorschriften zu Qualität, Sicherheit und Prüfung mit Kurzbeschreibung. Jede Zeile nennt nur, wofür die Norm steht, nicht den Inhalt.","lang":"**Qualitätsmanagement**\n\n- DIN EN ISO 9000: Grundlagen und Begriffe\n- DIN EN ISO 9001: Anforderungen an ein QM-System (zertifizierbar), siehe [[bg-iso-9001|ISO 9001]]\n- DIN EN ISO 9004: Leitfaden für nachhaltigen Erfolg und Verbesserung\n- DIN EN ISO 19011: Leitfaden zum Auditieren, siehe [[bg-audit|Audit]]\n- DIN 55350: Begriffe der Qualitätssicherung und Statistik, enthält die Begriffsbestimmung für Qualität\n\n**Maschinen- und Anlagensicherheit**\n\n- Maschinenrichtlinie 2006/42/EG (wird durch die EU-Maschinenverordnung abgelöst)\n- ISO 13849-1: Sicherheitsbezogene Teile von Steuerungen, Performance Level a bis e\n- IEC 62061: Funktionale Sicherheit von Maschinensteuerungen, SIL 1 bis 3\n- DIN EN 60204-1: Elektrische Ausrüstung von Maschinen\n- siehe [[bg-maschinensicherheit|Maschinensicherheit]]\n\n**Elektrische Sicherheit und Prüfung**\n\n- DIN VDE 0100: Errichten von Niederspannungsanlagen\n- DIN VDE 0701 und 0702: Prüfung nach Instandsetzung und Wiederholungsprüfung elektrischer Geräte, siehe [[ger-iso|Isolations- und Geräteprüfgerät]]\n- DIN VDE 0105: Betrieb von elektrischen Anlagen\n\n**Gefahrstoffe und Zeichen**\n\n- CLP-Verordnung der EU (GHS): Einstufung und Kennzeichnung, siehe [[bg-gefahrstoffe|Gefahrstoffkennzeichnung]]\n- DIN EN ISO 7010: Sicherheitszeichen\n\n**Hinweis**\n\nNormen werden regelmäßig überarbeitet. Maßgeblich ist immer die aktuelle Ausgabe.","verweise":["bg-iso-9001","bg-audit","bg-maschinensicherheit","ger-iso","bg-gefahrstoffe"],"labs":["pr","mess"],"stich":["Normen","DIN","ISO","VDE","EN","Richtlinie","Normenreihe"],"pruef":2,"status":"entwurf"},
  {"id":"fo-opv-verstaerkung","kat":"formel","titel":"Verstärkung der Operationsverstärker-Grundschaltungen","kurz":"Beim gegengekoppelten OPV bestimmen nur die Widerstände die Verstärkung: invertierend v = −R₂ / R₁, nichtinvertierend v = 1 + R₂ / R₁. Der Ausgang kann die Betriebsspannung nicht überschreiten.","lang":"Voraussetzung: Gegenkopplung und ein im Vergleich zu den Widerständen hoher Eingangswiderstand. Dann ist die Eingangsdifferenzspannung nahezu null (virtueller Kurzschluss).\n\n**Invertierend**: R₁ am Eingang, R₂ als Rückführung. Der Strom durch R₁ gleicht dem durch R₂, daher U_A / U_E = −R₂ / R₁.\n\n**Nichtinvertierend**: Spannungsteiler aus R₁ nach Masse und R₂ im Rückführzweig, U_A / U_E = 1 + R₂ / R₁.\n\n**Addierer** (invertierend): U_A = −R_F · (U₁ / R₁ + U₂ / R₂ + …).\n\nÜbungswert: R₁ = 10 kΩ, R₂ = 100 kΩ, U_E = 0,5 V. Invertierend ergibt U_A = −5 V. Nichtinvertierend ergibt v = 11, U_A = 5,5 V (bei ausreichender Betriebsspannung).\n\nOhne Gegenkopplung wirkt ein OPV als Komparator, der bei kleinster Differenz an die Betriebsspannung läuft. Siehe [[bg-opv-schaltungen|OPV-Schaltungen]], [[bg-opv-grundlagen|OPV-Grundlagen]], [[bt-opa|Operationsverstärker]].","verweise":["bg-opv-schaltungen","bg-opv-grundlagen","bt-opa"],"labs":["ana","sim"],"stich":["Verstärkung","invertierend","nichtinvertierend","Addierer","Rückkopplungswiderstand"],"pruef":3,"status":"entwurf","formeln":[{"text":"invertierend: v = −R₂ / R₁"},{"text":"nichtinvertierend: v = 1 + R₂ / R₁"},{"text":"Addierer: U_A = −R_F · (U₁/R₁ + U₂/R₂ + …)"}]},
  {"id":"fo-brutto-netto","kat":"formel","titel":"Von Brutto zu Netto","kurz":"Das Nettoentgelt ist das Bruttoentgelt abzüglich Lohnsteuer, eventueller Zuschläge dazu (Solidaritätszuschlag, Kirchensteuer) und Sozialversicherungsbeiträgen. Der Auszahlungsbetrag ist das Netto nach sonstigen Abzügen.","lang":"**Rechenweg**\n\n1. Bruttoentgelt: Grundlohn plus Zulagen und Sonderzahlungen\n2. minus Lohnsteuer, Solidaritätszuschlag, Kirchensteuer (gesetzliche Abzüge)\n3. minus Arbeitnehmeranteil an Kranken-, Pflege-, Renten- und Arbeitslosenversicherung\n4. gleich Nettoentgelt\n5. minus sonstige Abzüge (zum Beispiel vermögenswirksame Anlage), gleich Auszahlungsbetrag\n\n**Beispiel (nur Zahlenspiel)**\n\nBrutto 3000 €, gesetzliche Abzüge 700 €: Netto 2300 €. Der Arbeitgeber trägt zusätzlich seinen Anteil an der [[bg-sozialversicherung|Sozialversicherung]] und die Unfallversicherung, das ist nicht auf dem Netto sichtbar.\n\n**Stundenlohn**\n\nStundenlohn = Monatsentgelt geteilt durch die vereinbarten Monatsstunden. Zuschläge werden als Prozente vom Grundlohn gerechnet ([[fo-prozentrechnung|Prozentrechnung]]).\n\nHintergrund: [[bg-entgeltabrechnung|Entgelt und Lohnformen]].","formeln":[{"text":"Netto = Brutto − Steuern − Arbeitnehmeranteile Sozialversicherung"},{"text":"Auszahlung = Netto − sonstige Abzüge"},{"text":"Stundenlohn = Monatsentgelt / Monatsstunden"}],"verweise":["bg-sozialversicherung","fo-prozentrechnung","bg-entgeltabrechnung"],"labs":["pr"],"stich":["Brutto","Netto","Auszahlungsbetrag","Stundenlohn","Lohnsteuer"],"pruef":2,"status":"entwurf"},
  {"id":"fo-zdiode-vorwiderstand","kat":"formel","titel":"Vorwiderstand der Z-Dioden-Stabilisierung","kurz":"Der Vorwiderstand muss so gewählt werden, dass die Z-Diode bei maximaler Eingangsspannung und kleinster Last nicht überlastet wird und bei minimaler Eingangsspannung und größter Last noch ihren Mindeststrom bekommt.","lang":"Grenzen für R_V:\n\n- R_V,min = (U_e,max − U_Z) / (I_Z,max + I_L,min), im Leerlauf ist I_L,min = 0.\n- R_V,max = (U_e,min − U_Z) / (I_Z,min + I_L,max).\n\nÜbungswert: U_Z = 6,2 V, U_e = 15 bis 20 V, I_Z,max = 30 mA, I_Z,min = 8 mA, I_L,max = 5 mA. R_V,min = 13,8 V / 30 mA = 460 Ω. R_V,max = 8,8 V / 13 mA ≈ 677 Ω. Gewählt aus der E24-Reihe: 560 Ω.\n\nPrüfung: Bei 20 V und Leerlauf fließen 13,8 V / 560 Ω ≈ 24,6 mA durch die Diode, das sind P ≈ 6,2 V · 24,6 mA ≈ 150 mW (unter P_tot). Bei 15 V und voller Last bleibt 8,8 V / 560 Ω − 5 mA ≈ 10,7 mA, also über I_Z,min. Der kleinste zulässige Lastwiderstand ist R_L,min = U_Z / I_L,max = 1,24 kΩ.\n\nDie Stabilisierung steht in [[bg-z-diode|Z-Diode]], die Verwendung im [[bg-netzteilarten|Netzteil]]. Bauteil: [[bt-d|Diode]].","verweise":["bg-z-diode","bg-netzteilarten","bt-d"],"labs":["nts","sim","ana"],"stich":["Z-Dioden-Schaltung","Vorwiderstand","Stabilisierungsschaltung","I_Z,max","E24"],"pruef":3,"status":"entwurf","formeln":[{"text":"R_V,min = (U_e,max − U_Z) / (I_Z,max + I_L,min)"},{"text":"R_V,max = (U_e,min − U_Z) / (I_Z,min + I_L,max)"}]},
  {"id":"fo-zener-vorwiderstand","kat":"formel","titel":"Vorwiderstand einer Z-Diode","kurz":"Der Vorwiderstand ergibt sich aus Spannungsfall durch Gesamtstrom: R_V = (U_e − U_Z) / (I_Z + I_L). Zenerstrom und Verlustleistungen müssen innerhalb der Grenzen bleiben.","lang":"Der Strom durch R_V teilt sich in Zenerstrom I_Z und Laststrom I_L. Der Höchstwert des Zenerstroms folgt aus der zulässigen Verlustleistung: I_Zmax = P_tot / U_Z. Der Mindeststrom darf nie unterschritten werden; als Faustregel etwa ein Zehntel des Höchstwerts (je nach Datenblatt).\n\nBeispiel (Übungswert): U_e = 12 V, U_Z = 6,2 V, I_Z = 15 mA, keine Last. R_V = 5,8 V / 0,015 A = 386,7 Ω, gewählt 390 Ω. Leistung am Vorwiderstand: 5,8 V · 15 mA = 87 mW. Leistung in der Z-Diode: 6,2 V · 15 mA = 93 mW. Mit einer Last von 10 mA wäre R_V = 5,8 V / 25 mA = 232 Ω.\n\nZum Prüfen der Grenzen rechnet man mit größter Eingangsspannung bei kleinster Last (größter Zenerstrom) und mit kleinster Eingangsspannung bei größter Last (kleinster Zenerstrom). Beispiel für die Leistungsgrenze: P_tot = 360 mW, U_Z = 4,7 V: I_Zmax = 76,6 mA. Siehe [[bg-z-dioden-stabilisierung|Stabilisierung mit Z-Diode]] und [[bt-d|Diode]]. Anwendung im Netzteil: [[bg-spannungsstabilisierung|Spannungsstabilisierung]].","verweise":["bg-z-dioden-stabilisierung","bt-d","bg-spannungsstabilisierung"],"labs":["nts","sim"],"stich":["Z-Diode","Vorwiderstand","Zenerstrom","Verlustleistung"],"pruef":3,"formeln":[{"text":"R_V = (U_e − U_Z) / (I_Z + I_L)"},{"text":"I_Zmax = P_tot / U_Z"},{"text":"P_V = (U_e − U_Z)² / R_V"}],"status":"entwurf"},
  {"id":"fo-led-vorwiderstand","kat":"formel","titel":"Vorwiderstand für eine LED","kurz":"Der Vorwiderstand begrenzt den Strom einer Leuchtdiode: R_V = (U_q − U_F) / I_F. Er nimmt die Differenz zwischen Quellenspannung und Flussspannung auf.","lang":"Eine LED darf nie ohne Strombegrenzung betrieben werden. Mit der Quellenspannung U_q, der Flussspannung U_F der LED und dem gewünschten Strom I_F gilt:\n\nR_V = (U_q − U_F) / I_F.\n\nÜbungswert: U_q = 5 V, U_F = 2 V, I_F = 10 mA ergibt R_V = 3 V / 10 mA = 300 Ω. Aus der E12-Reihe wählst du 330 Ω; es fließen dann 3 V / 330 Ω ≈ 9,1 mA. Die Verlustleistung im Widerstand beträgt etwa U_R · I = 3 V · 9,1 mA ≈ 27 mW.\n\nBei mehreren LEDs in Reihe addierst du die Flussspannungen. Die Flussspannung hängt von Material und Farbe ab.\n\nBauteile: [[bt-led|LED]], [[bt-r|Widerstand]]; Hintergrund in [[bg-sonderdioden|Sonderdioden]].","verweise":["bt-led","bt-r","bg-sonderdioden"],"labs":["sim","sch","loch","code"],"stich":["LED-Vorwiderstand","Flussspannung","Strombegrenzung","E12","Vorwiderstand"],"pruef":3,"status":"entwurf","formeln":[{"text":"R_V = (U_q − U_F) / I_F"}]},
  {"id":"fo-wechselgroessen","kat":"formel","titel":"Wechselgrößen und Induktionsgesetz","kurz":"Für eine Sinusgröße gelten T = 1 / f, û = √2 · U und φ = 360° · Δt / T. Das Induktionsgesetz beschreibt die Spannung durch Flussänderung, u_i = −N · ΔΦ / Δt.","lang":"**Periode und Frequenz**: f = 1 / T. 50 Hz entsprechen T = 20 ms.\n\n**Effektiv und Scheitel** (nur Sinus): û = √2 · U ≈ 1,414 · U. Übungswert: 230 V Effektivwert, û ≈ 325 V. Der Gleichrichtwert ist etwa 0,637 · û.\n\n**Phasenverschiebung** aus dem Zeitversatz Δt zweier Kurven auf dem Oszilloskop: φ = 360° · Δt / T. Übungswert: f = 1 kHz (T = 1 ms) und Δt = 0,25 ms ergeben 90°. Bei Drehstrom sind die Spannungen 120° versetzt, bei 50 Hz sind das 6,67 ms.\n\n**Oszilloskop**: T = Anzahl Teile · Zeitkoeffizient. Übungswert: 4 Teile bei 2 ms/Teil ergeben T = 8 ms, f = 125 Hz. Spannung: U_SS = Teile · Volt/Teil.\n\n**Induktionsgesetz**: u_i = −N · ΔΦ / Δt. Übungswert: N = 1000, ΔΦ = 0,6 mVs, Δt = 3 ms ergibt |u_i| = 200 V. Das Minus steht für die Lenzsche Regel.\n\nSiehe [[bg-wechselspannung|Wechselspannung]] und [[bg-induktion|Induktion]]; Messen mit dem [[ger-oszi|Oszilloskop]].","verweise":["bg-wechselspannung","bg-induktion","ger-oszi"],"labs":["wsl","mess","ant"],"stich":["Periodendauer","Effektivwert","Scheitelwert","Phasenwinkel","Zeitversatz","Induktionsspannung","Gleichrichtwert"],"pruef":3,"status":"entwurf","formeln":[{"text":"f = 1 / T"},{"text":"û = √2 · U"},{"text":"φ = 360° · Δt / T"},{"text":"u_i = −N · ΔΦ / Δt"}]},
  {"id":"fo-wertebereich","kat":"formel","titel":"Wertebereich bei n Bit","kurz":"Mit n Bit lassen sich 2 hoch n verschiedene Werte darstellen. Ohne Vorzeichen reicht der Bereich von 0 bis 2ⁿ − 1.","lang":"Jedes zusätzliche Bit verdoppelt die Zahl der Werte.\n\nBeispiele (Übungswerte): 4 Bit: 16 Werte (0 bis 15). 8 Bit: 256 Werte (0 bis 255). 10 Bit: 1024 Werte (0 bis 1023), das entspricht einem 10-Bit-Analog-Digital-Wandler mit 1024 Stufen. Mit Vorzeichen im Zweierkomplement reichen 8 Bit von −128 bis +127.\n\nBei Zählern bestimmt n das Teilerverhältnis ([[fo-teilerverhaeltnis|Frequenzteiler]]), bei Adressen die Zahl der Speicherstellen ([[fo-speicherkapazitaet|Speicherkapazität]]). Für negative Zahlen siehe [[fo-zweierkomplement|Zweierkomplement]].","verweise":["fo-teilerverhaeltnis","fo-speicherkapazitaet","fo-zweierkomplement"],"labs":["digi"],"stich":["Bit","Wertebereich","Auflösung","Stufen"],"pruef":3,"formeln":[{"text":"Anzahl Werte = 2ⁿ"},{"text":"größter Wert (ohne Vorzeichen) = 2ⁿ − 1"},{"text":"Zweierkomplement: −2ⁿ⁻¹ … +2ⁿ⁻¹ − 1"}],"status":"entwurf"},
  {"id":"nw-datenblatt-formelzeichen","kat":"norm","titel":"Wortliste: Formelzeichen im Datenblatt","kurz":"Wortliste der Formelzeichen und englischen Begriffe, die in Datenblättern von Dioden, Transistoren und Schaltkreisen stehen. Hinter dem Zeichen steht die englische Bezeichnung und ihre deutsche Bedeutung.","lang":"**Dioden und Leuchtdioden**\n\n- V_F (oder U_F): Forward Voltage = Durchlassspannung\n- I_F: Forward Current = Durchlassstrom\n- V_R (oder U_R): Reverse Voltage = Sperrspannung\n- I_R: Reverse Current = Sperrstrom\n- P_tot: Total Power Dissipation = Gesamtverlustleistung\n\n**Transistoren**\n\n- I_C: Collector Current = Kollektorstrom\n- V_CE: Collector-Emitter Voltage = Kollektor-Emitter-Spannung\n- V_BE: Base-Emitter Voltage = Basis-Emitter-Spannung\n- h_FE (oder β): DC Current Gain = Gleichstromverstärkung\n- V_GS, I_D, R_DS(on): Gate-Source Voltage, Drain Current, On-State Resistance (MOSFET)\n\n**Schaltkreise**\n\n- V_CC, V_DD: Supply Voltage = Versorgungsspannung\n- V_SS, GND: Ground = Masse\n- I_CC, I_Q: Supply Current, Quiescent Current = Stromaufnahme, Ruhestrom\n- V_IH, V_IL: High / Low Level Input Voltage = Eingangspegel High / Low\n- V_OH, V_OL: Output High / Low Voltage = Ausgangspegel\n- t_r, t_f: Rise Time, Fall Time = Anstiegs- und Abfallzeit\n- t_pd: Propagation Delay = Laufzeit\n- f_max: Maximum Frequency = höchste Frequenz\n\n**Allgemein**\n\n- T_A: Ambient Temperature = Umgebungstemperatur\n- T_J: Junction Temperature = Sperrschichttemperatur\n- T_stg: Storage Temperature = Lagertemperatur\n- R_th: Thermal Resistance = Wärmewiderstand\n\nAufbau eines Datenblatts: [[bg-englisch-datenblatt|Datenblatt]]. Grenzwerte erklärt [[bg-englisch-grenzwerte|Grenzwerte]]. Bauteile: [[bt-d|Diode]], [[bt-npn|Transistor]], [[bt-ic|Schaltkreis]].","verweise":["bg-englisch-datenblatt","bg-englisch-grenzwerte","bt-d","bt-npn","bt-ic"],"labs":["ds"],"stich":["Formelzeichen","Datenblatt","VCC","VF","IF","datasheet","Wortliste"],"pruef":3,"status":"entwurf"},
  {"id":"fo-zweierkomplement","kat":"formel","titel":"Zweierkomplement und Subtraktion","kurz":"Negative Ganzzahlen werden im Zweierkomplement dargestellt: alle Bits invertieren und 1 addieren. Damit lässt sich Subtrahieren als Addieren ausführen.","lang":"Bildung des Zweierkomplements bei 8 Bit: Einerkomplement (alle Bits umkehren), dann plus 1.\n\nBeispiel (Übungswert): +5 = 0000 0101. Invertiert: 1111 1010. Plus 1: 1111 1011. Das ist −5 (hex FB, dezimal 251 − 256).\n\nSubtraktion: A − B = A + (Zweierkomplement von B), also A + NICHT B + 1. Beispiel: 3 − 5 = 0000 0011 + 1111 1011 = 1111 1110 = −2. Das Vorzeichenbit (höchstes Bit) ist 1, im Statusregister wird das Sign-Flag gesetzt ([[bg-flags|Flags]]). Bei der Subtraktion mit Borrow ist das negative Ergebnis das Zweierkomplement des wahren Betrags. Die ALU ([[bg-cpu-aufbau|CPU]]) nutzt dafür denselben Addierer.","verweise":["bg-flags","bg-cpu-aufbau","fo-wertebereich"],"labs":["digi","code"],"stich":["Zweierkomplement","negativ","Subtraktion","Vorzeichen"],"pruef":2,"formeln":[{"text":"−B = NICHT B + 1"},{"text":"A − B = A + NICHT B + 1"}],"status":"entwurf"}
]);
